    '''    pub fn validate_generated(sdk: &ValidatedSdk, stage: &Path) -> Result<(), RenpyError> {\n        for command in [\n            vec![command_path(stage), OsString::from("compile")],\n            vec![\n                command_path(stage),\n                OsString::from("lint"),\n                OsString::from("--error-code"),\n            ],\n        ] {\n            sdk.revalidate(false)?;\n            let result = require_success(run_bounded(\n                &sdk.root,\n                launcher_args(&sdk.root, &command)?,\n                Duration::from_secs(180),\n            )?);\n            sdk.revalidate(false)?;\n            result?;\n        }\n        Ok(())\n    }\n\n    pub fn generate_starter_anchored(\n        sdk: &ValidatedSdk,\n        stage: &Path,\n        stage_anchor: &File,\n        width: u32,\n        height: u32,\n    ) -> Result<(), RenpyError> {\n        #[cfg(windows)]\n        {\n            let _ = stage_anchor;\n            Self::generate_starter(sdk, stage, width, height)\n        }\n        #[cfg(unix)]\n        {\n            let _ = stage;\n            let args = [\n                OsString::from("launcher"),\n                OsString::from("generate_gui"),\n                OsString::from("."),\n                OsString::from("--width"),\n                OsString::from(width.to_string()),\n                OsString::from("--height"),\n                OsString::from(height.to_string()),\n                OsString::from("--template"),\n                sdk.root.join("gui").into_os_string(),\n                OsString::from("--start"),\n            ];\n            sdk.revalidate(true)?;\n            let result = require_success(run_bounded_anchored(\n                &sdk.root,\n                stage_anchor,\n                launcher_args(&sdk.root, &args)?,\n                Duration::from_secs(180),\n            )?);\n            sdk.revalidate(true)?;\n            result\n        }\n    }\n\n    pub fn validate_generated_anchored(\n        sdk: &ValidatedSdk,\n        stage: &Path,\n        stage_anchor: &File,\n    ) -> Result<(), RenpyError> {\n        #[cfg(windows)]\n        {\n            let _ = stage_anchor;\n            Self::validate_generated(sdk, stage)\n        }\n        #[cfg(unix)]\n        {\n            let _ = stage;\n            for command in [\n                vec![OsString::from("."), OsString::from("compile")],\n                vec![\n                    OsString::from("."),\n                    OsString::from("lint"),\n                    OsString::from("--error-code"),\n                ],\n            ] {\n                sdk.revalidate(false)?;\n                let result = require_success(run_bounded_anchored(\n                    &sdk.root,\n                    stage_anchor,\n                    launcher_args(&sdk.root, &command)?,\n                    Duration::from_secs(180),\n                )?);\n                sdk.revalidate(false)?;\n                result?;\n            }\n            Ok(())\n        }\n    }\n''',
